# ── code intelligence ────────────────────────────────────────────────────────
# Appended after the original literal so the list above stays diffable. The
# handler is actions/repo_tool.py::repo_inspect and it is read-only: it indexes
# source files (skipping credentials and build output) and reports symbols,
# imports and matches. Nothing is written and no project code is executed.
TOOL_DECLARATIONS.append({
    'name': 'repo_inspect',
    'description': (
        "Inspects a project folder before changing it: file inventory, Python "
        "symbols (class/function/method with line numbers), what imports what, "
        "and targeted text search. Use this for 'what is in this project', "
        "'where is X defined', 'what uses this module', 'find where this string "
        "lives', 'which tests exist' — instead of reading files one by one. "
        "Read-only: it never writes, never runs the project, and never reads "
        ".env, api_keys.json, secrets.enc, private keys or config/certs. "
        "Actions: summary (default) | search | symbol | file | imports | tests."
    ),
    'parameters': {
        'type': 'OBJECT',
        'properties': {
            'action': {'type': 'STRING',
                       'description': 'summary | search | symbol | file | imports | tests'},
            'root': {'type': 'STRING',
                     'description': 'Project folder to inspect (default: the current workspace)'},
            'query': {'type': 'STRING',
                      'description': 'Text (search), symbol name (symbol), file path (file) or module name (imports)'},
            'regex': {'type': 'BOOLEAN',
                      'description': 'Treat query as a regular expression for search (default false)'},
            'limit': {'type': 'INTEGER',
                      'description': 'Maximum results to return (default 40)'},
        },
        'required': ['action'],
    },
})

# ── live feature demo ────────────────────────────────────────────────────────
# "Demo" is a first-class request: the assistant performs each capability in
# front of the user (real search, real browser, real documents, real builds)
# instead of describing them. Handler: actions/feature_demo.py.
TOOL_DECLARATIONS.append({
    'name': 'feature_demo',
    'description': (
        "Live feature demo — THE tool for 'demo', 'key demo', 'run the demo', "
        "'show me all your features', 'show what you can do by actually doing "
        "it', 'demonstrate your capabilities'. It performs the capabilities "
        "for real, one after another, narrating on the activity timeline: "
        "system status, live web search, browser control (opens a page and "
        "reads it), document creation (Word/Excel/PowerPoint), screen vision, "
        "code intelligence, long-term memory, messaging readiness (read-only, "
        "nothing is sent), website build, dashboard build (served and opened), "
        "desktop app build, and a coding-agent CLI run. Artifacts are written "
        "to ~/Desktop/keys_Creations/demo/<timestamp> and the run survives the "
        "conversation continuing. The demo records a demo_report.json but it "
        "does NOT open the demo folder or preview its example artifacts on disk. "
        "NEVER describe the demo instead of calling this tool — call it and then "
        "report what actually passed. Actions: run (default) | status | stop | list."
    ),
    'parameters': {
        'type': 'OBJECT',
        'properties': {
            'action': {'type': 'STRING',
                       'description': 'run (default) | status | stop | list'},
            'fast': {'type': 'BOOLEAN',
                     'description': 'Skip the slower build steps, keeping the quick ones (default false)'},
            'steps': {'type': 'STRING',
                      'description': 'Optional comma-separated subset: system, search, browser, documents, vision, repo, memory, messaging, site, dashboard, desktop, code'},
        },
        'required': [],
    },
})

